import React, { useEffect, useMemo } from "react";
import ajax from "@/utils/ajax";
import store from "./store";
import { Button, Dropdown, List, Menu, Message, Modal, Space, Tabs, Typography, Select, Tooltip, Alert } from "@arco-design/web-react";
import styles from './style.module.less';
import { SchemaTable } from "@/components/schema";
import { scrollToElementById } from "@/utils";
import { useObserver } from "mobx-react-lite";
import { IconQuestionCircle, IconSettings } from "@arco-design/web-react/icon";
import dictionary from "@/store/dictionary";
import plugin from "@/store/plugin";
import DictionaryTable from '@/components/custom/DictionaryTable';
import plugins from "@/store/plugins";
import app from "@/store/app";
import { toJS } from "mobx";


const Index = () => {

    useEffect(() => {
        store.init();
        plugins.init();
    },[])

    
    return useObserver(() => {


        const allDatasheets = useMemo(() => {
            // 过滤所有存在的插件
            return toJS(plugins.list).filter((o) => {
                const item = app.extraInfo.plugins[o.pluginId];
                return item && item.isActive;
            }).reduce((keys, item) => {
                return [...keys, ...item.extraInfo.datasheets]
            }, [])
        }, [plugins.list])


        const list = dictionary.getTables(allDatasheets);

        return (
            <div className="pb-4 h-full flex flex-col">
                <Alert content="当前业务数据仅供参考，默认管理员账号 admin/123456" />
                <div className="bg-white flex-grow">
                    <Tabs
                        className={"arco-tabs-page"}
                        key={list.length}
                        defaultActiveTab={list[0]?.tableName}
                        extra={(
                            <Space>
                                {/* <Button type="primary"
                                    onClick={() => {
                                        store.setSelectValues(plugin.extraInfo.datasheets)
                                        store.setVisible(true)
                                    }}
                                >添加</Button> */}
                                <Dropdown 
                                    droplist={(
                                        <Menu>
                                            <Menu.Item key='1' 
                                                onClick={() =>{
                                                    Modal.confirm({
                                                        title: "提示",
                                                        content: "请确认是否进行数据初始化，此操作会重置当前系统 用户/角色等信息",
                                                        onOk: () => {
                                                            ajax.post(`/data-manage/init`, {}).then((res) => {
                                                                Message.success("数据初始化")
                                                            })
                                                        }
                                                    })
                                                }}
                                            >初始化</Menu.Item>
                                        </Menu>
                                    )} 
                                    trigger='click' position='br'
                                >
                                    <Button icon={<IconSettings />} />
                                </Dropdown>
                            </Space>
                        )}
                    >
                        {list.map((o) => (
                            <Tabs.TabPane
                                key={o.tableName}
                                title={(
                                    <Space>
                                        <span>{o.tableName}</span>
                                        {o.desc? (
                                            <Tooltip content={o.desc}>
                                                <IconQuestionCircle />
                                            </Tooltip>
                                        ): null}
                                    </Space>
                                )}
                            >
                                <DictionaryTable table={o} className="p-4" />
                            </Tabs.TabPane>
                        ))}
                    </Tabs>
                </div>
                <Modal visible={store.visible}
                    title="插件数据表绑定"
                    onCancel={() => {
                        store.setVisible(false)
                    }}
                    onOk={() => {
                        plugin.assignExtraInfo({
                            datasheets: store.selectValues
                        })
                        return plugin.savaExtraInfo().then(() => {
                            store.setVisible(false);
                        })
                    }}
                >
                    <Select
                        value={store.selectValues}
                        options={dictionary.getOptions()}
                        mode="multiple"
                        onChange={store.setSelectValues}
                    />
                </Modal>
            </div>
        )
    })
}

export default Index;